using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using StockManagement.Data;using StockManagement.Models;using StockManagement.Services;
namespace StockManagement.Controllers;[Authorize(Roles=Roles.Admin+","+Roles.Manager)] public class PurchasesController:Controller{readonly ApplicationDbContext _db;readonly AuditService _audit;public PurchasesController(ApplicationDbContext db,AuditService audit){_db=db;_audit=audit;}public IActionResult Index()=>View(_db.Purchases.Include(x=>x.Supplier).OrderByDescending(x=>x.PurchaseDate).ToList());public IActionResult Create(){ViewBag.Products=_db.Products.OrderBy(x=>x.Name).ToList();ViewBag.Suppliers=_db.Suppliers.Where(x=>x.IsActive).OrderBy(x=>x.Name).ToList();return View(new PurchaseCreateVm());}[HttpPost,ValidateAntiForgeryToken]public IActionResult Create(PurchaseCreateVm vm){ViewBag.Products=_db.Products.OrderBy(x=>x.Name).ToList();ViewBag.Suppliers=_db.Suppliers.Where(x=>x.IsActive).OrderBy(x=>x.Name).ToList();var lines=vm.Lines.Where(x=>x.ProductId>0&&x.Quantity>0).ToList();if(vm.SupplierId<=0)ModelState.AddModelError("SupplierId","Select a supplier.");if(!lines.Any())ModelState.AddModelError("","Add at least one product.");if(!ModelState.IsValid)return View(vm);using var tx=_db.Database.BeginTransaction();try{var purchase=new Purchase{SupplierId=vm.SupplierId,InvoiceNo="PO-"+DateTime.Now.ToString("yyyyMMddHHmmss")};foreach(var l in lines){var p=_db.Products.Find(l.ProductId)??throw new Exception("Product not found");purchase.Details.Add(new PurchaseDetail{ProductId=p.Id,Quantity=l.Quantity,UnitCost=l.UnitCost});p.CurrentStock+=l.Quantity;}purchase.TotalAmount=purchase.Details.Sum(x=>x.Quantity*x.UnitCost);_db.Purchases.Add(purchase);_db.SaveChanges();tx.Commit();_audit.Add("Purchase","Create",$"Purchase {purchase.InvoiceNo} created for {purchase.TotalAmount:N2}",User.Identity?.Name??"System");TempData["Success"]=$"Purchase {purchase.InvoiceNo} created successfully.";return RedirectToAction(nameof(Index));}catch(Exception ex){tx.Rollback();ModelState.AddModelError("",ex.Message);return View(vm);}}
public IActionResult Details(int id){var p=_db.Purchases.Include(x=>x.Supplier).Include(x=>x.Details).ThenInclude(x=>x.Product).FirstOrDefault(x=>x.Id==id);return p==null?NotFound():View(p);}}
